1	//! Status-line and terminal-title rendering helpers for `ChatWidget`.
2	//!
3	//! Keeping this logic in a focused submodule makes the additive title/status
4	//! behavior easier to review without paging through the rest of `chatwidget.rs`.
5	
6	use super::*;
7	
8	/// Items shown in the terminal title when the user has not configured a
9	/// custom selection. Intentionally minimal: spinner + project name.
10	pub(super) const DEFAULT_TERMINAL_TITLE_ITEMS: [&str; 2] = ["spinner", "project"];
11	
12	/// Braille-pattern dot-spinner frames for the terminal title animation.
13	pub(super) const TERMINAL_TITLE_SPINNER_FRAMES: [&str; 10] =
14	    ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
15	
16	/// Time between spinner frame advances in the terminal title.
17	pub(super) const TERMINAL_TITLE_SPINNER_INTERVAL: Duration = Duration::from_millis(100);
18	
19	/// Compact runtime states that can be rendered into the terminal title.
20	///
21	/// This is intentionally smaller than the full status-header vocabulary. The
22	/// title needs short, stable labels, so callers map richer lifecycle events
23	/// onto one of these buckets before rendering.
24	#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
25	pub(super) enum TerminalTitleStatusKind {
26	    Working,
27	    WaitingForBackgroundTerminal,
28	    Undoing,
29	    #[default]
30	    Thinking,
31	}
32	
33	#[derive(Debug)]
34	/// Parsed status-surface configuration for one refresh pass.
35	///
36	/// The status line and terminal title share some expensive or stateful inputs
37	/// (notably git branch lookup and invalid-item warnings). This snapshot lets one
38	/// refresh pass compute those shared concerns once, then render both surfaces
39	/// from the same selection set.
40	struct StatusSurfaceSelections {
41	    status_line_items: Vec<StatusLineItem>,
42	    invalid_status_line_items: Vec<String>,
43	    terminal_title_items: Vec<TerminalTitleItem>,
44	    invalid_terminal_title_items: Vec<String>,
45	}
46	
47	impl StatusSurfaceSelections {
48	    fn uses_git_branch(&self) -> bool {
49	        self.status_line_items.contains(&StatusLineItem::GitBranch)
50	            || self
51	                .terminal_title_items
52	                .contains(&TerminalTitleItem::GitBranch)
53	    }
54	}
55	
56	/// Cached project-root display name keyed by the cwd used for the last lookup.
57	///
58	/// Terminal-title refreshes can happen very frequently, so the title path avoids
59	/// repeatedly walking up the filesystem to rediscover the same project root name
60	/// while the working directory is unchanged.
61	#[derive(Clone, Debug)]
62	pub(super) struct CachedProjectRootName {
63	    pub(super) cwd: PathBuf,
64	    pub(super) root_name: Option<String>,
65	}
66	
67	impl ChatWidget {
68	    fn status_surface_selections(&self) -> StatusSurfaceSelections {
69	        let (status_line_items, invalid_status_line_items) = self.status_line_items_with_invalids();
70	        let (terminal_title_items, invalid_terminal_title_items) =
71	            self.terminal_title_items_with_invalids();
72	        StatusSurfaceSelections {
73	            status_line_items,
74	            invalid_status_line_items,
75	            terminal_title_items,
76	            invalid_terminal_title_items,
77	        }
78	    }
