1	//! Terminal-title output helpers for the TUI.
2	//!
3	//! This module owns the low-level OSC title write path and the sanitization
4	//! that happens immediately before we emit it. It is intentionally narrow:
5	//! callers decide when the title should change and whether an empty title means
6	//! "leave the old title alone" or "clear the title Codex last wrote".
7	//! This module does not attempt to read or restore the terminal's previous
8	//! title because that is not portable across terminals.
9	//!
10	//! Sanitization is necessary because title content is assembled from untrusted
11	//! text sources such as model output, thread names, project paths, and config.
12	//! Before we place that text inside an OSC sequence, we strip:
13	//! - control characters that could terminate or reshape the escape sequence
14	//! - bidi/invisible formatting codepoints that can visually reorder or hide
15	//!   text (the same family of issues discussed in Trojan Source writeups)
16	//! - redundant whitespace that would make titles noisy or hard to scan
17	
18	use std::fmt;
19	use std::io;
20	use std::io::IsTerminal;
21	use std::io::stdout;
22	
23	use crossterm::Command;
24	use ratatui::crossterm::execute;
25	
26	/// Practical upper bound on title length, measured in Rust `char`s.
27	///
28	/// Most terminals silently truncate titles beyond a few hundred characters.
29	/// 240 leaves headroom for the OSC framing bytes while keeping titles
30	/// readable in tab bars and window managers.
31	const MAX_TERMINAL_TITLE_CHARS: usize = 240;
32	
33	/// Outcome of a [`set_terminal_title`] call.
34	#[derive(Debug, Clone, Copy, Eq, PartialEq)]
35	pub(crate) enum SetTerminalTitleResult {
36	    /// A sanitized title was written, or stdout is not a terminal so no write was needed.
37	    Applied,
38	    /// Sanitization removed every visible character, so no title was emitted.
39	    ///
40	    /// This is distinct from clearing the title. Callers decide whether an
41	    /// empty post-sanitization value should result in no-op behavior, clearing
42	    /// the title Codex manages, or some other fallback.
43	    NoVisibleContent,
44	}
45	
46	/// Writes a sanitized OSC window-title sequence to stdout.
47	///
48	/// The input is treated as untrusted display text: control characters,
49	/// invisible formatting characters, and redundant whitespace are removed before
50	/// the title is emitted. If sanitization removes all visible content, the
51	/// function returns [`SetTerminalTitleResult::NoVisibleContent`] instead of
52	/// clearing the title because clearing and restoring are policy decisions for
53	/// higher-level callers. Mechanically, sanitization collapses whitespace runs
54	/// to single spaces, drops disallowed codepoints, and bounds the result to
55	/// [`MAX_TERMINAL_TITLE_CHARS`] visible characters before writing OSC 0.
56	pub(crate) fn set_terminal_title(title: &str) -> io::Result<SetTerminalTitleResult> {
57	    if !stdout().is_terminal() {
58	        return Ok(SetTerminalTitleResult::Applied);
59	    }
60	
61	    let title = sanitize_terminal_title(title);
62	    if title.is_empty() {
63	        return Ok(SetTerminalTitleResult::NoVisibleContent);
64	    }
65	
66	    execute!(stdout(), SetWindowTitle(title))?;
67	    Ok(SetTerminalTitleResult::Applied)
68	}
69	
70	/// Clears the current terminal title by writing an empty OSC title payload.
71	///
72	/// This clears the visible title; it does not restore whatever title the shell
73	/// or a previous program may have set before Codex started managing the title.
74	pub(crate) fn clear_terminal_title() -> io::Result<()> {
75	    if !stdout().is_terminal() {
76	        return Ok(());
77	    }
78	
79	    execute!(stdout(), SetWindowTitle(String::new()))
80	}
81	
82	#[derive(Debug, Clone)]
83	struct SetWindowTitle(String);
84	
85	impl Command for SetWindowTitle {
86	    fn write_ansi(&self, f: &mut impl fmt::Write) -> fmt::Result {
87	        // xterm/ctlseqs documents OSC 0/2 title sequences with ST (ESC \) termination.
88	        // Most terminals also accept BEL for compatibility, but ST is the canonical form.
89	        write!(f, "\x1b]0;{}\x1b\\", self.0)
90	    }
91	
92	    #[cfg(windows)]
93	    fn execute_winapi(&self) -> io::Result<()> {
94	        Err(std::io::Error::other(
95	            "tried to execute SetWindowTitle using WinAPI; use ANSI instead",
96	        ))
97	    }
98	
99	    #[cfg(windows)]
100	    fn is_ansi_code_supported(&self) -> bool {
101	        true
102	    }
103	}
104	
105	/// Normalizes untrusted title text into a single bounded display line.
106	///
107	/// This removes terminal control characters, strips invisible/bidi formatting
108	/// characters, collapses any whitespace run into a single ASCII space, and
109	/// truncates after [`MAX_TERMINAL_TITLE_CHARS`] emitted characters.
110	fn sanitize_terminal_title(title: &str) -> String {
111	    let mut sanitized = String::new();
112	    let mut chars_written = 0;
113	    let mut pending_space = false;
114	
115	    for ch in title.chars() {
116	        if ch.is_whitespace() {
117	            // Only set pending if we've already written content; this
118	            // strips leading whitespace without an extra trim pass.
119	            pending_space = !sanitized.is_empty();
120	            continue;
121	        }
122	
123	        if is_disallowed_terminal_title_char(ch) {
124	            continue;
125	        }
126	
127	        if pending_space {
128	            let remaining = MAX_TERMINAL_TITLE_CHARS.saturating_sub(chars_written);
129	            if remaining > 1 {
130	                sanitized.push(' ');
131	                chars_written += 1;
132	                pending_space = false;
133	            }
134	        }
135	
136	        if chars_written >= MAX_TERMINAL_TITLE_CHARS {
137	            break;
138	        }
139	
140	        sanitized.push(ch);
141	        chars_written += 1;
142	    }
143	
144	    sanitized
145	}
146	
147	/// Returns whether `ch` should be dropped from terminal-title output.
148	///
149	/// This includes both plain control characters and a curated set of invisible
150	/// formatting codepoints. The bidi entries here cover the Trojan-Source-style
151	/// text-reordering controls that can make a title render misleadingly relative
152	/// to its underlying byte sequence.
153	fn is_disallowed_terminal_title_char(ch: char) -> bool {
154	    if ch.is_control() {
155	        return true;
156	    }
157	
158	    // Strip Trojan-Source-related bidi controls plus common non-rendering
159	    // formatting characters so title text cannot smuggle terminal control
160	    // semantics or visually misleading content.
161	    matches!(
162	        ch,
163	        '\u{00AD}'
164	            | '\u{034F}'
165	            | '\u{061C}'
166	            | '\u{180E}'
167	            | '\u{200B}'..='\u{200F}'
168	            | '\u{202A}'..='\u{202E}'
169	            | '\u{2060}'..='\u{206F}'
170	            | '\u{FE00}'..='\u{FE0F}'
171	            | '\u{FEFF}'
172	            | '\u{FFF9}'..='\u{FFFB}'
173	            | '\u{1BCA0}'..='\u{1BCA3}'
174	            | '\u{E0100}'..='\u{E01EF}'
175	    )
176	}
